def solve(workspace):
    n = workspace.length()
    for i in range(n - 1):
        for j in range(n - 1 - i):
            if workspace.peek(j) > workspace.peek(j + 1):
                workspace.swap_adjacent(j)
                workspace.swap_adjacent(j + 1)

def solve(arr):
    preserve_pairs = [(0, 2), (3, 0), (5, 0), (1, 5)]
    elements = list(set(arr))
    elements.sort()
    for i, j in preserve_pairs:
        if i < j:
            elements[i], elements[j] = elements[j], elements[i]
    return elements
